def jup_pa(san: int) -> bool:
    """San jup bolsa True qaytaradı."""
    return san % 2 == 0

def eń_úlken(sanlar: list[int]) -> int:
    """Dizimdegi eń úlken sandı qaytaradı."""
    if not sanlar:
        raise ValueError("dizim bos")
    natiyje = sanlar[0]
    for san in sanlar[1:]:
        if san > natiyje:
            natiyje = san
    return natiyje

def qosındı(n: int) -> int:
    """1 den n ge shekemgi sanlardıń qosındısın qaytaradı."""
    return n * (n + 1) // 2

def tákirarsız(elementler: list[str]) -> list[str]:
    """Tákirarlarsız dizim qaytaradı, dáslepki tártipti saqlaydı."""
    kórilgen: set[str] = set()
    natiyje: list[str] = []
    for element in elementler:
        if element not in kórilgen:
            kórilgen.add(element)
            natiyje.append(element)
    return natiyje
